async function imageFileToDataUrl(file){const data=await new Promise((resolve,reject)=>{const fr=new FileReader();fr.onerror=()=>reject(fr.error);fr.onload=()=>{const img=new Image();img.onload=()=>{const max=1280,scale=Math.min(1,max/Math.max(img.width,img.height)),w=Math.max(1,Math.round(img.width*scale)),h=Math.max(1,Math.round(img.height*scale)),c=document.createElement('canvas');c.width=w;c.height=h;c.getContext('2d').drawImage(img,0,0,w,h);resolve({canvas:c,data:c.toDataURL('image/jpeg',.78)})};img.onerror=()=>resolve({canvas:null,data:String(fr.result||'')});img.src=String(fr.result||'')};fr.readAsDataURL(file)});try{if(data.canvas){const blob=await new Promise(r=>data.canvas.toBlob(r,'image/jpeg',.78));if(blob){const fd=new FormData();fd.append('image',blob,'status.jpg');const res=await fetch(`${API}/upload`,{method:'POST',body:fd});if(res.ok){const out=await res.json();if(out.url)return out.url}}}}catch(e){console.warn('image upload fallback',e)}return data.data}

