function maybeFollowBack(a){if(!a||a.type!=='celeb'||followsMe(a.id)||!followBackEligible(a))return;const r=memoryFor(a.id),publicTouches=(state.memory||[]).filter(m=>m.celebrityId===a.id&&(m.type==='comment_reply'||m.type==='verified_public'||m.type==='event')).length,base=a.reach>=100000000?.08:a.reach>=30000000?.16:.26,chance=clamp(base+state.player.fame/450+r.friendship/220+r.trust/300+publicTouches*.025,.03,.62);if(Math.random()<chance){state.followedByIds.push(a.id);remember('follow_back',{celebrityId:a.id,celebrity:a.name});verifiedPublicImpact(a,true,'follow');addNotif(`${a.name} followed you back.`,'follow',{celebrityId:a.id});save();render()}}
