function openSearch(){showSheet('Search',`<div class="searchbox"><span>⌕</span><input id="celebritysearch" autocomplete="off" placeholder="Search celebrities and news"></div><div id="searchresults" class="searchresults"></div>`);const input=$('#celebritysearch'),out=$('#searchresults');const draw=()=>{const q=input.value.trim().toLowerCase(),items=ACCOUNTS.filter(a=>!q||a.name.toLowerCase().includes(q)||a.handle.toLowerCase().includes(q)).slice(0,30);out.innerHTML=items.map(a=>`<div class="searchresult"><button class="searchidentity" data-profile="${a.id}">${av(a)}<div><strong>${esc(a.name)} ${check()}</strong><span>@${esc(a.handle)} · ${esc(a.role)}${followsMe(a.id)?' · Follows you':''}</span></div></button><button class="searchfollow ${isFollowing(a.id)?'on':''}" data-search-follow="${a.id}">${isFollowing(a.id)?'Following':'Follow'}</button></div>`).join('')||'<div class="empty">No profiles found.</div>';out.querySelectorAll('[data-profile]').forEach(b=>b.onclick=()=>openProfile(b.dataset.profile));out.querySelectorAll('[data-search-follow]').forEach(b=>b.onclick=e=>{e.stopPropagation();const id=b.dataset.searchFollow,a=byId(id);if(isFollowing(id)){state.followingIds=state.followingIds.filter(x=>x!==id);remember('unfollow',{celebrityId:id,celebrity:a.name});save();flash(`Unfollowed ${a.name}`)}else{state.followingIds.push(id);remember('follow',{celebrityId:id,celebrity:a.name});save();flash(`Following ${a.name}`);if(a.type==='celeb')setTimeout(()=>maybeFollowBack(a),rand(2500,8500))}draw()})};input.oninput=draw;draw();setTimeout(()=>input.focus(),80)}

async function installPageTracks(files=[]){
 const list=[...files].filter(f=>/\.mp3$/i.test(f.name)||String(f.type).toLowerCase()==='audio/mpeg'),mapped={};
 for(const f of list){const n=f.name.toLowerCase();if(/main|feed|home/.test(n))mapped.main=f;else if(/career|work/.test(n))mapped.career=f;else if(/circle/.test(n))mapped.circle=f;else if(/(^|[^a-z])you([^a-z]|$)|profile/.test(n))mapped.you=f}
 const missing=['main','career','circle','you'].filter(k=>!mapped[k]);
 const status=$('#pagetrackstatus');
 if(missing.length){if(status)status.textContent=`Missing: ${missing.join(', ')}`;flash('Choose the 4 MP3s labelled Main, Career, Circle and You.');return}
 try{
   let i=0;for(const slot of ['main','career','circle','you']){i++;if(status)status.textContent=`Installing ${i}/4 · ${slot==='main'?'Main':slot[0].toUpperCase()+slot.slice(1)}…`;const fd=new FormData();fd.append('file',mapped[slot],mapped[slot].name);const r=await fetch(`${API}/page-track-ingest?token=scene-audio-bridge-119-k7p2&slot=${slot}`,{method:'POST',body:fd});if(!r.ok)throw new Error(`Upload failed: ${slot}`)}
   const rev=String(now());localStorage.setItem('scene-page-tracks-ready','1');localStorage.setItem('scene-page-track-rev',rev);if(status)status.textContent='Installed · Main · Career · Circle · You';await Sound.reloadPageTracks();flash('♫ Page soundtrack installed');
 }catch(e){console.warn('SCENE page soundtrack install failed',e);if(status)status.textContent='Install failed · tap Install to retry';flash('Could not install all 4 tracks')}
}

