 document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{const tab=b.dataset.tab,at=now(),same=state.tab===tab,double=same&&sceneTabTap.tab===tab&&at-sceneTabTap.at<430;sceneTabTap.tab=tab;sceneTabTap.at=at;if(double){sceneScrollTop();return}state.tab=tab;if(state.music)void Sound.switchForTab(state.tab);save();render()});
