function openEvent(ev){if(!ev)return;showSheet('Event',`<div class="eventhero"><div class="eventtag">LIVE SITUATION</div><h3>${esc(ev.title)}</h3><p>${esc(ev.body)}</p></div><div class="heading">What do you do?</div>${ev.choices.map((c,i)=>`<button class="eventchoice" data-eventchoice="${i}">${esc(c[0])}<span>›</span></button>`).join('')}`);document.querySelectorAll('[data-eventchoice]').forEach(b=>b.onclick=()=>{const c=ev.choices[+b.dataset.eventchoice];applyEffect(c[1]);state.player.xp+=4;state.events.unshift(`${ev.title}: ${c[0]}`);remember('event',{title:ev.title,choice:c[0],effect:c[1]});const labels={money:'cash',fame:'fame',rep:'reputation',followers:'followers',energy:'energy',xp:'XP',gems:'diamonds'},effectText=Object.entries(c[1]||{}).map(([k,v])=>`${v>0?'+':''}${v} ${labels[k]||k}`).join(' · ');addNotif(`${ev.badge||'Event'}${effectText?` · ${effectText}`:''}.`,'career');state.pendingEvent=null;save();closeModal();render();flash('The world noticed.')});}
function notifGlyph(kind){return kind==='follow'?'＋':kind==='like'?'♥':kind==='comment'?'◌':kind==='reply'?'↩':kind==='mention'||kind==='news'?'@':kind==='dm'?'✉':kind==='fame'?'✦':kind==='career'?'◎':kind==='connection'?'◇':kind==='world'?'◉':'•'}
function notifLabel(n){const k=n.kind||'world';return k==='follow'?'FOLLOW':k==='like'?'LIKES':k==='comment'?'COMMENT':k==='reply'?'REPLY':k==='mention'||k==='news'?'MENTION':k==='dm'?'MESSAGE':k==='fame'?'FAME':k==='career'?'CAREER':k==='connection'?'CONNECTION':k==='world'?'WORLD':'UPDATE'}
function notificationRow(n){const channel=n.channel||notifChannel(n.kind),actor=n.celebrityId?byId(n.celebrityId):null,action=n.kind==='dm'&&n.celebrityId?` data-notif-dm="${esc(n.celebrityId)}"`:n.postId?` data-notif-post="${esc(n.postId)}"`:n.celebrityId?` data-notif-profile="${esc(n.celebrityId)}"`:'';return `<button class="activityrow ${n.unread?'fresh':''} ${channel}"${action}>${actor&&channel==='social'?av(actor,'notifavatar'):`<span class="activityicon">${notifGlyph(n.kind)}</span>`}<div class="grow"><div class="activitymeta"><b>${notifLabel(n)}</b><time>${ago(n.at)} ago</time></div><strong>${esc(n.text)}</strong></div>${n.unread?'<i class="activityunread"></i>':''}</button>`}
function activityDisplayItems(view){const raw=state.notifications.filter(n=>(n.channel||notifChannel(n.kind))===view),out=[];for(const n of raw){const mergeable=view==='social'&&n.postId&&!n.celebrityId&&['like','comment'].includes(n.kind);if(!mergeable){out.push({...n});continue}const prior=out.find(x=>x.kind===n.kind&&x.postId===n.postId&&!x.celebrityId&&Math.abs((x.at||0)-(n.at||0))<10*60000);if(!prior){out.push({...n,amount:Number(n.amount)||1});continue}prior.amount=(Number(prior.amount)||1)+(Number(n.amount)||1);prior.unread=prior.unread||n.unread;prior.at=Math.max(prior.at||0,n.at||0);prior.text=n.kind==='like'?`${fmt(prior.amount)} new likes on your post.`:`${fmt(prior.amount)} new comments on your post.`}return out}
function openActivity(view=state.activityView||'social'){state.activityView=view;const beforeSocial=unreadCount('social'),beforeProgress=unreadCount('progress'),items=activityDisplayItems(view);for(const n of state.notifications){if((n.channel||notifChannel(n.kind))===view)n.unread=false}save();const p=state.player,summary=view==='social'?`<div class="activitystats"><div><b>${fmt(p.followers)}</b><span>Followers</span></div><div><b>${fmt(playerFollowingCount())}</b><span>Following</span></div><div><b>${items.length}</b><span>Activity</span></div></div>`:`<div class="activitystats progressstats"><div><b>${p.fame}</b><span>Fame</span></div><div><b>LVL ${lvl()}</b><span>Career</span></div><div><b>${moneyDisplay(p.money,p.city)}</b><span>Cash</span></div></div>`;modal.innerHTML=`<div class="activitypage"><header class="activitynav"><div><span class="kicker">SCENE</span><h2>Activity</h2></div><button class="activityclose" id="activityclose">×</button></header><div class="activitytabs"><button class="${view==='social'?'on':''}" data-activity-view="social">Social${view!=='social'&&beforeSocial?` <b>${beforeSocial}</b>`:''}</button><button class="${view==='progress'?'on':''}" data-activity-view="progress">Progress${view!=='progress'&&beforeProgress?` <b>${beforeProgress}</b>`:''}</button></div>${summary}<div class="activityintro">${view==='social'?'<strong>Feed activity</strong><span>Follows, likes, comments, replies, mentions and messages.</span>':'<strong>Career ledger</strong><span>Rewards, fame changes, jobs, travel and opportunities — separate from your social feed.</span>'}</div><div class="activitylist ${view}">${items.length?items.map(notificationRow).join(''):`<div class="activityempty"><strong>${view==='social'?'Nothing social yet.':'Nothing new on the career side yet.'}</strong><span>${view==='social'?'Post, comment and build your audience to wake this up.':'Book a gig, finish a quest or hit an event, and it shows up here.'}</span></div>`}</div></div>`;$('#activityclose').onclick=()=>{closeModal();render()};modal.querySelectorAll('[data-activity-view]').forEach(b=>b.onclick=()=>openActivity(b.dataset.activityView));modal.querySelectorAll('[data-notif-dm]').forEach(b=>b.onclick=()=>openDm(b.dataset.notifDm));modal.querySelectorAll('[data-notif-post]').forEach(b=>b.onclick=()=>{const id=b.dataset.notifPost;if(state.posts.some(p=>p.id===id))openComments(id)});modal.querySelectorAll('[data-notif-profile]').forEach(b=>b.onclick=()=>openProfile(b.dataset.notifProfile));render()}
