function showSheet(title,body){clearTimeout(storyTimer);modal.innerHTML=`<div class="overlay"><div class="sheet"><div class="sheethead"><div class="sheettitle">${esc(title)}</div><button class="close" aria-label="Close">×</button></div>${body}</div></div>`;modal.querySelector('.close').onclick=closeModal;modal.querySelector('.overlay').onclick=e=>{if(e.target===e.currentTarget)closeModal()};modal.querySelectorAll('[data-profile]').forEach(b=>b.onclick=()=>openProfile(b.dataset.profile))}

